diff --git a/src/wasm/baseline/liftoff-compiler.cc b/src/wasm/baseline/liftoff-compiler.cc
index 464bbb3cd81..ffc4edab71f 100644
--- a/src/wasm/baseline/liftoff-compiler.cc
+++ b/src/wasm/baseline/liftoff-compiler.cc
@@ -6704,9 +6704,9 @@ class LiftoffCompiler {
     }
     ValueKind expected_kind = kind == kI32 ? kI32 : kRef;

-    // Compute index + offset into a fresh pointer-sized register after BigInt
-    // conversions. For memory32, zero-extend to uintptr to prevent 64-bit
-    // sign-extension of >=2GiB offsets.
+    // Compute index plus offset in a fresh pointer-sized register after the
+    // BigInt conversions. Explicitly checked memories use the signed 64-bit
+    // representation of a memory32 index on 64-bit targets.
     LiftoffRegList pinned{expected};
     LiftoffRegister index = pinned.set(__ PeekToRegister(2, pinned));

@@ -6725,7 +6725,14 @@ class LiftoffCompiler {
       }
     } else {
       index_plus_offset = pinned.set(__ GetUnusedRegister(kGpReg, pinned)).gp();
-      __ emit_u32_to_uintptr(index_plus_offset, index.gp());
+      if (imm.memory->bounds_checks == kExplicitBoundsChecks &&
+          kSystemPointerSize == 8) {
+        __ emit_type_conversion(kExprI64SConvertI32,
+                                LiftoffRegister{index_plus_offset},
+                                LiftoffRegister{index.gp()}, nullptr);
+      } else {
+        __ emit_u32_to_uintptr(index_plus_offset, index.gp());
+      }
       if (imm.offset) {
         __ emit_ptrsize_addi(index_plus_offset, index_plus_offset, imm.offset);
       }

